"use client";

import { animate } from "motion";
import type { AnimationOptions } from "motion";

/**
 * The desktop "Product" dropdown.
 *
 * The nav lives in `components/site/shell.tsx`, which is generated by
 * scripts/opsra_extract.py from the Framer export and must never be
 * hand-edited — so, exactly like `reveal.tsx` / `ticker.tsx` / `controls.tsx`,
 * this attaches by querying the export's own markers:
 *
 *   nav[data-framer-name="Desktop"]
 *     └ [data-framer-name="Nav Links Wrap"]        (.framer-vtc2dc)
 *         └ [data-framer-name="Text Button"] > p > a   ← one per nav link
 *
 * The anchor whose text is "Features" is relabelled "Product" and becomes the
 * disclosure trigger; the panel is inserted as the trigger wrapper's next
 * sibling so keyboard tab order runs Product → the 14 feature links → the rest
 * of the nav, and is positioned absolutely inside the (position: relative,
 * overflow: visible) links wrap. The trigger's original label and href are
 * captured at init and restored by the cleanup, so a teardown leaves the
 * generated markup byte-identical to what the server sent.
 *
 * Link targets: the 14 feature routes below are this menu's own content, but
 * the TRIGGER's href is read from the DOM and restored on teardown — the nav's
 * existing targets are owned by the extractor, not by this file.
 *
 * Desktop only. The export's breakpoints (from the `data-framer-hydrate-v2`
 * payload in shell.tsx) are:
 *   (min-width: 1320px)                          → Desktop
 *   (min-width: 810px) and (max-width: 1319.98px) → Tablet
 *   (max-width: 809.98px)                         → Phone
 * and site.css hides the non-matching `.ssr-variant` wrappers outright, so the
 * whole desktop nav — this panel included — is `display: none` below 1320px.
 * Opening is additionally gated on that same media query, so the panel can
 * never be shown on the tablet/phone nav, which another module owns.
 *
 * Motion is the site's own language, at nav speed: a `bounce: 0` spring, the
 * same family as the 1s scroll reveals in `reveal.tsx` (Framer
 * `{bounce: 0, duration: 1, type: "spring"}`), compressed to 280ms because a
 * nav dropdown must feel instant. `prefers-reduced-motion` shows/hides it with
 * no animation at all.
 */

type Cleanup = () => void;

/* ------------------------------------------------------------------ *
 * Content                                                             *
 * ------------------------------------------------------------------ */

interface FeatureLink {
  /** Rendered uppercase by the stylesheet, like every other nav label. */
  label: string;
  href: string;
  /** One line. Derived from the product, not invented — see `source`. */
  blurb: string;
  /** Where the description came from, for the next person to check. */
  source: string;
}

interface FeatureGroup {
  title: string;
  items: readonly FeatureLink[];
}

